    const occupiedPort = occupied.address().port;

    const certDir = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-httpsfail-"));
    const tls = ensureSelfSignedTls({ dir: certDir, extraSans: [] });
    const proxy = createLanProxy({
